+import { pool } from "./pool.ts";
+
+export interface JobResponse {
+  id: string;
+  payload: string;
+}
+
+export const claimJobForNotifications = async (): Promise<JobResponse | null> => {
+  const result = await pool.query(
+    "SELECT id, payload FROM jobs WHERE status = 'ready' ORDER BY created_at LIMIT 1",
+  );
+  const row = result.rows[0];
+  if (row === undefined) return null;
+  await pool.query("UPDATE jobs SET status = 'claimed' WHERE id = $1", [row.id]);
+  return { id: row.id, payload: row.payload };
+};
+
+export const completeJob = async (jobId: string): Promise<void> => {
+  await pool.query("UPDATE jobs SET status = 'completed' WHERE id = $1", [jobId]);
+};
+
+export const failJob = async (jobId: string, reason?: string): Promise<void> => {
+  await pool.query(
+    "UPDATE jobs SET status = 'failed', error = $1 WHERE id = $2",
+    [reason || null, jobId],
+  );
+};
