+import { createServer, IncomingMessage, ServerResponse } from "http";
+import { claimJobForNotifications, completeJob, failJob, type JobResponse } from "./api.ts";
+
+const PORT = process.env.NOTIFICATIONS_API_PORT || 3001;
+
+const sendJSON = (res: ServerResponse, status: number, data: unknown): void => {
+  res.writeHead(status, { "Content-Type": "application/json" });
+  res.end(JSON.stringify(data));
+};
+
+const sendError = (res: ServerResponse, status: number, message: string): void => {
+  sendJSON(res, status, { error: message });
+};
+
+export const startServer = (): void => {
+  const server = createServer(async (req: IncomingMessage, res: ServerResponse) => {
+    res.setHeader("Access-Control-Allow-Origin", "*");
+
+    const [path, query] = req.url?.split("?") || [];
+
+    if (req.method === "GET" && path === "/jobs/next") {
+      try {
+        const job = await claimJobForNotifications();
+        if (job === null) {
+          sendJSON(res, 204, null);
+          return;
+        }
+        sendJSON(res, 200, job);
+      } catch (error) {
+        sendError(res, 500, "Failed to claim job");
+      }
+      return;
+    }
+
+    if (req.method === "POST" && path?.startsWith("/jobs/")) {
+      const jobId = path.split("/")[2];
+      const action = path.split("/")[3];
+
+      if (action === "complete") {
+        try {
+          await completeJob(jobId);
+          sendJSON(res, 200, { success: true });
+        } catch (error) {
+          sendError(res, 500, "Failed to complete job");
+        }
+        return;
+      }
+
+      if (action === "fail") {
+        let body = "";
+        req.on("data", (chunk) => {
+          body += chunk;
+        });
+        req.on("end", async () => {
+          try {
+            const { reason } = JSON.parse(body || "{}");
+            await failJob(jobId, reason);
+            sendJSON(res, 200, { success: true });
+          } catch (error) {
+            sendError(res, 500, "Failed to fail job");
+          }
+        });
+        return;
+      }
+    }
+
+    sendError(res, 404, "Not found");
+  });
+
+  server.listen(PORT, () => {
+    console.log(`Notifications API listening on port ${PORT}`);
+  });
+};
